await check("Review checkbox enables save, and changing any suggested fact revokes it",async()=>{const h=harness();await h.open();await h.find("Review suggested intake").fire("click");let form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);assert.equal(h.find("Save reviewed intake draft").disabled,false);await set(form,"title","Reviewed correction");assert.equal(input(form,"confirmed").checked,false);assert(h.find("Save reviewed intake draft").disabled);await set(form,"confirmed",true);await set(form,"quantity","2");assert.equal(input(form,"confirmed").checked,false);});
