await check("Reviewed save creates only one ordinary intake and reopens its saved source link",async()=>{const h=harness();await h.open();await h.find("Review suggested intake").fire("click");const form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);h.handler=(p,o)=>{if(o&&p.endsWith("/accept")){h.row.consumed_intake_id="J-fixture";h.response.inbox.packets[0].consumed_intake_id="J-fixture";return h.reply(p,o);}if(p==="/service-desk/intakes/J-fixture")return {revision:h.response.revision,intake:{id:"J-fixture",client_id:"client-one",provider:profile(),content_sha256:"6".repeat(64),...facts(),intake_packet:{packet_id:pid,packet_content_sha256:"4".repeat(64),raw_sha256:"1".repeat(64),text_sha256:"2".repeat(64),facts_sha256:"7".repeat(64)}}};return h.reply(p,o);};await form.fire("submit");assert.equal(h.writes().length,1);assert.equal(h.writes()[0].path,"/service-desk/inbox/accept");assert.equal(h.writes()[0].options.body.intake.permission.confirmed,false);assert(!h.calls.some(x=>x.options&&/quotes|invoices|review$|export/.test(x.path)));assert.match(h.body.textContent,/already created intake J-fixture/);assert(h.find("Inspect linked source packet"));assert(h.find("Generate quote draft"));});
