await check("Structured feature discovery and packet opening never generate or fetch a proposal",async()=>{const h=harness({response:structuredBoard()});await h.open();assert(h.find("Ask local model for suggestions"));assert.equal(h.writes().length,0);assert(!h.calls.some(x=>x.path.includes("/proposals")));assert.match(h.body.textContent,/one bounded local request/);assert.match(h.body.textContent,/Valid JSON and an exact source quote do not prove/);});
await check("Configured callback is never mislabeled as loaded-model readiness",async()=>{const h=harness({response:structuredBoard({available:false,reason:"No local structured provider configured"})});await h.open();assert(h.find("Ask local model for suggestions").disabled);await h.find("Ask local model for suggestions").fire("click");assert.equal(h.writes().length,0);assert.match(h.body.textContent,/No local structured provider/);assert(h.find("Review suggested intake"));});
await check("One explicit generation binds packet hash and revision without URL model or approval controls",async()=>{const h=harness({response:structuredBoard()});await h.open();await h.find("Ask local model for suggestions").fire("click");assert.equal(h.writes().length,1);const call=h.writes()[0];assert.equal(call.path,"/service-desk/inbox/proposals");assert.equal(call.options.body.expected_revision,7);assert.equal(call.options.body.packet_id,pid);assert.equal(call.options.body.content_sha256,"4".repeat(64));assert.deepEqual(Object.keys(call.options.body).sort(),["content_sha256","expected_revision","packet_id","request_id"]);assert(h.calls.some(x=>x.path==="/service-desk/inbox/proposals/"+xid&&!x.options));assert(h.find("Review model-assisted intake"));assert.equal(h.row.content_sha256,"4".repeat(64));});
await check("Concurrent generation gestures produce exactly one request",async()=>{const h=harness({response:structuredBoard()});await h.open();const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const button=h.find("Ask local model for suggestions"),first=button.fire("click");await button.fire("click");assert.equal(h.writes().length,1);h.api.locked();wait.resolve({status:"completed",entity_id:xid});await first;assert.equal(h.toasts.length,0);});
await check("Model candidates retain literal source code-point spans and separate proposal fingerprints",async()=>{const h=harness({response:structuredBoard(),withProposal:true});await h.open();await h.find("fixture-model · "+new Date("2026-11-02T12:05:00Z").toLocaleString()+" · "+xid).fire("click");assert.match(h.body.textContent,/Proposal X-/);for(const digest of ["c".repeat(64),"a".repeat(64),"b".repeat(64),"d".repeat(64)])assert(h.body.textContent.includes(digest));assert.match(h.body.textContent,/Line 1 · characters 5–21/);assert.equal(h.writes().length,0);});
await check("Evidence validation rejects wrong-source wrong-client malformed-digest and active-field proposals",async()=>{const h=harness(),base=modelProposal(),source=packet();for(const change of [{schema:2},{packet_id:"P-"+"e".repeat(24)},{packet_content_sha256:"f".repeat(64)},{text_sha256:"f".repeat(64)},{client_id:"client-two"},{client_content_sha256:"f".repeat(64)},{schema_sha256:"broken"},{response_sha256:"broken"},{candidates:[{...base.candidates[0],field:"permission.confirmed"}]},{candidates:[{...base.candidates[0],start:0}]},{candidates:[{...base.candidates[0],end:999999}]},{warnings:[{}]}])assert.equal(h.api.validProposal({...base,...change},source),false,JSON.stringify(change));assert.equal(h.api.validProposal(base,source),true);});
await check("Unicode model evidence uses code-point offsets instead of UTF16 indexes",async()=>{const h=harness();const source=packet({text:"🧵 Name"}),row=modelProposal(source,{candidates:[{field:"customer.name",value:"Name",quote:"Name",start:2,end:6,line_number:1,quote_sha256:"a".repeat(64)}]});assert.equal(h.api.validProposal(row,source),true);assert.equal(h.api.validProposal({...row,candidates:[{...row.candidates[0],start:3,end:7}]},source),false);});
await check("Corrupted proposal read fails closed before displaying any suggested facts",async()=>{const bad=modelProposal(packet(),{packet_content_sha256:"f".repeat(64)}),h=harness({response:structuredBoard(),proposalRow:bad,withProposal:true});await h.open();await h.find("fixture-model · "+new Date(bad.created_at).toLocaleString()+" · "+xid).fire("click");assert.match(h.body.textContent,/could not be verified against/);assert(!h.find("Review model-assisted intake"));assert(h.find("Save job intake").disabled);assert.equal(h.writes().length,0);});
await check("Model review is explicit and strips every commercial approval even from a hostile proposed intake",async()=>{const proposed=facts();proposed.lines[0].price_approved=true;proposed.tax={bps:0,approved:true,source_ref:"untrusted"};proposed.permission={confirmed:true,source_ref:"untrusted"};const h=harness({response:structuredBoard(),proposalRow:modelProposal(packet(),{proposed_intake:proposed})});await h.open();await h.find("Ask local model for suggestions").fire("click");assert(!h.find("Save reviewed intake draft"));await h.find("Review model-assisted intake").fire("click");const form=formOf(h.find("Save reviewed intake draft"));assert.match(form.textContent,/Review the model-assisted/);for(const name of ["price_approved","tax_approved","permission_confirmed"])assert.equal(input(form,name),undefined);assert(h.find("Save reviewed intake draft").disabled);await set(form,"confirmed",true);await form.fire("submit");const body=h.writes().at(-1).options.body;assert.equal(body.proposal_id,xid);assert.equal(body.proposal_sha256,"c".repeat(64));assert.equal(body.content_sha256,"4".repeat(64));assert.equal(body.intake.lines[0].price_approved,false);assert.equal(body.intake.tax.approved,false);assert.equal(body.intake.permission.confirmed,false);assert(!h.writes().some(x=>/quotes|invoices|review$|export/.test(x.path)));});
await check("Editing a model-assisted field or line revokes source review",async()=>{const h=harness({response:structuredBoard()});await h.open();await h.find("Ask local model for suggestions").fire("click");await h.find("Review model-assisted intake").fire("click");let form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);await set(form,"title","Owner correction");assert(h.find("Save reviewed intake draft").disabled);await set(form,"confirmed",true);await h.find("Add service line").fire("click");assert(h.find("Save reviewed intake draft").disabled);});
await check("Switching back to deterministic suggestions removes model provenance from the save payload",async()=>{const h=harness({response:structuredBoard()});await h.open();await h.find("Ask local model for suggestions").fire("click");await h.find("Review suggested intake").fire("click");const form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);await form.fire("submit");const body=h.writes().at(-1).options.body;assert(!Object.hasOwn(body,"proposal_id"));assert(!Object.hasOwn(body,"proposal_sha256"));});
await check("Empty accepted candidate sets show warnings without inventing a model-assisted review",async()=>{const h=harness({response:structuredBoard(),proposalRow:modelProposal(packet(),{candidates:[],warnings:["Conflicting quantity was left unresolved"]})});await h.open();await h.find("Ask local model for suggestions").fire("click");assert.match(h.body.textContent,/No model suggestions passed/);assert.match(h.body.textContent,/Conflicting quantity/);assert(!h.find("Review model-assisted intake"));assert(h.find("Review suggested intake"));});
await check("Changed-client and consumed proposals remain historical rather than new intake authority",async()=>{for(const change of [{client_changed:true},{consumed_intake_id:"J-existing"}]){const h=harness({response:structuredBoard(),proposalRow:modelProposal(packet(),change)});await h.open();await h.find("Ask local model for suggestions").fire("click");assert(!h.find("Review model-assisted intake"));assert.throws(()=>h.api.proposalAcceptPayload(h.row,modelProposal(h.row,change),{},8,"test-save",true));}});
await check("Global pause holds model generation while proposal evidence remains readable",async()=>{const h=harness({response:structuredBoard(),withProposal:true});await h.open();h.app.state.status.paused=true;h.api.status();assert(h.find("Ask local model for suggestions").disabled);await h.find("Ask local model for suggestions").fire("click");await h.find("fixture-model · "+new Date("2026-11-02T12:05:00Z").toLocaleString()+" · "+xid).fire("click");assert(h.find("Review model-assisted intake"));assert.equal(h.writes().length,0);});
await check("A durable extraction hold disables generation but preserves manual source review",async()=>{const hold={request_id:"held-generation",status:"failed",entity_id:xid,receipt_sha256:"e".repeat(64),reason:"Synthetic model failure"},h=harness({response:structuredBoard({hold})});await h.open();assert(h.find("Ask local model for suggestions").disabled);assert.match(h.body.textContent,/holds another model request, not manual intake/);assert(h.find("Review suggested intake"));assert.equal(h.find("Save job intake").disabled,false);assert(h.find("Acknowledge inspected extraction hold").disabled);});
await check("Hold acknowledgement is explicit exact-hash CAS and never starts generation",async()=>{const hold={request_id:"held-generation",status:"interrupted",entity_id:xid,receipt_sha256:"e".repeat(64),reason:"Inspect uncertain result"},h=harness({response:structuredBoard({hold})});await h.open();await set(h.body,"confirmed",true);await h.find("Acknowledge inspected extraction hold").fire("click");assert.equal(h.writes().length,1);const call=h.writes()[0];assert.equal(call.path,"/service-desk/inbox/proposals/acknowledge");assert.equal(call.options.body.request_id,"held-generation");assert.equal(call.options.body.expected_revision,7);assert.equal(call.options.body.receipt_sha256,"e".repeat(64));assert.equal(call.options.body.inspection_confirmed,true);assert(!h.writes().some(x=>x.path.endsWith("/proposals")));assert.equal(h.find("Ask local model for suggestions").disabled,false);});
await check("Lost model replies hold the browser and never auto-dispatch another generation",async()=>{const h=harness({response:structuredBoard()});await h.open();h.handler=(p,o)=>{if(o)throw Error("Synthetic generation response lost");return h.reply(p,o);};await h.find("Ask local model for suggestions").fire("click");assert.match(h.body.textContent,/nothing is retried automatically/);assert(h.find("Ask local model for suggestions").disabled);h.handler=null;await h.api.load();assert.equal(h.writes().length,1);});
await check("Leaving while generation is in flight retains uncertainty and discards its late proposal",async()=>{const h=harness({response:structuredBoard()});await h.open();const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const first=h.find("Ask local model for suggestions").fire("click");h.api.leave();wait.resolve({status:"completed",entity_id:xid});await first;h.handler=null;await h.api.load();assert.match(h.body.textContent,/response was interrupted/);assert.equal(h.writes().length,1);assert(!h.calls.some(x=>x.path==="/service-desk/inbox/proposals/"+xid));assert.equal(h.toasts.length,0);});
await check("Lock clears model evidence and discards a late proposal read",async()=>{const h=harness({response:structuredBoard(),withProposal:true});await h.open();const wait=deferred();h.handler=(p,o)=>p.includes("/proposals/")?wait.promise:h.reply(p,o);const opening=h.find("fixture-model · "+new Date("2026-11-02T12:05:00Z").toLocaleString()+" · "+xid).fire("click");await Promise.resolve();await Promise.resolve();await Promise.resolve();h.api.locked();wait.resolve({schema:1,revision:7,proposal:modelProposal()});await opening;assert.equal(h.body.childNodes[0].textContent,"");assert(!h.body.textContent.includes("fixture-model"));assert.equal(h.writes().length,0);});
await check("Model text remains inert and can never supply executable markup",async()=>{const source=packet({text:"<script>bad()</script>"}),candidate={field:"title",value:"<script>bad()</script>",quote:"<script>bad()</script>",start:0,end:22,line_number:1,quote_sha256:"d".repeat(64)},h=harness({response:structuredBoard(),row:source,proposalRow:modelProposal(source,{candidates:[candidate]})});candidate.end=Array.from(candidate.quote).length;await h.open();await h.find("Ask local model for suggestions").fire("click");assert.equal(h.all().filter(x=>x.tagName==="SCRIPT").length,0);assert.match(h.body.textContent,/<script>bad\(\)<\/script>/);});
await check("In-flight generation has honest progress and cannot accept another gesture",async()=>{const h=harness({response:structuredBoard()});await h.open();const wait=deferred();h.handler=(p,o)=>o?wait.promise:h.reply(p,o);const button=h.find("Ask local model for suggestions"),pending=button.fire("click");assert.equal(button.textContent,"Reading with local model…");assert.equal(button.attrs["aria-busy"],"true");assert(button.disabled);assert.match(h.body.textContent,/One request is in progress/);h.api.locked();wait.resolve({status:"completed",entity_id:xid});await pending;});
await check("Recorded running work is not falsely declared interrupted and active acknowledgement may be refused",async()=>{const hold={request_id:"held-generation",status:"running",entity_id:xid,receipt_sha256:"e".repeat(64),reason:"Incomplete or possibly active"},h=harness({response:structuredBoard({hold})});await h.open();assert.match(h.body.textContent,/incomplete or possibly active/);assert.doesNotMatch(h.body.textContent,/request was interrupted/);await set(h.body,"confirmed",true);h.handler=(p,o)=>{if(o)throw Object.assign(Error("A structured extraction is active"),{status:409});return h.reply(p,o);};await h.find("Acknowledge inspected extraction hold").fire("click");assert.match(h.body.textContent,/structured extraction is active/);assert(h.find("Ask local model for suggestions").disabled);assert.equal(h.writes().length,1);});
await check("Changed receipt hashes revoke a previous hold-inspection confirmation",async()=>{const hold={request_id:"held-generation",status:"failed",entity_id:xid,receipt_sha256:"e".repeat(64),reason:"Inspect failure"},h=harness({response:structuredBoard({hold})});await h.open();await set(h.body,"confirmed",true);assert.equal(h.find("Acknowledge inspected extraction hold").disabled,false);h.response.structured_extraction.hold.receipt_sha256="f".repeat(64);await h.api.load();assert(h.find("Acknowledge inspected extraction hold").disabled);assert.equal(input(h.body,"confirmed").checked,false);assert.equal(h.writes().length,0);});
await check("Saved model provenance reopens its historical proposal after the source is consumed",async()=>{const h=harness({response:structuredBoard()});await h.open();await h.find("Ask local model for suggestions").fire("click");await h.find("Review model-assisted intake").fire("click");const form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);await form.fire("submit");assert.match(h.body.textContent,/already created intake J-fixture/);assert(h.find("Inspect reviewed model proposal"));await h.find("Inspect reviewed model proposal").fire("click");assert.match(h.body.textContent,/Reviewed local-model proposal/);assert.match(h.body.textContent,/Proposal X-/);assert(!h.find("Review model-assisted intake"));assert(h.find("Ask local model for suggestions").disabled);assert.equal(h.writes().length,2);});
await check("Saved model proposals remain readable when no generation provider is configured",async()=>{const h=harness({response:structuredBoard({available:false,reason:"Provider unavailable for new generation"}),withProposal:true});await h.open();assert(h.find("Ask local model for suggestions").disabled);await h.find("fixture-model · "+new Date("2026-11-02T12:05:00Z").toLocaleString()+" · "+xid).fire("click");assert.match(h.body.textContent,/Proposal X-/);assert(h.find("Review model-assisted intake"));assert(h.calls.some(x=>x.path==="/service-desk/inbox/proposals/"+xid&&!x.options));assert.equal(h.writes().length,0);assert(!h.calls.some(x=>x.options&&x.path.endsWith("/proposals")));});
await check("Disabling the provider keeps historical proposal review and intake acceptance independent of inference",async()=>{const h=harness({response:structuredBoard()});await h.open();await h.find("Ask local model for suggestions").fire("click");await h.find("Review model-assisted intake").fire("click");h.response.structured_extraction.available=false;h.response.structured_extraction.reason="No provider configured now";await h.api.load();assert(h.find("Ask local model for suggestions").disabled);const form=formOf(h.find("Save reviewed intake draft"));await set(form,"confirmed",true);await form.fire("submit");assert.equal(h.writes().filter(x=>x.path.endsWith("/proposals")).length,1);assert.equal(h.writes().filter(x=>x.path==="/service-desk/inbox/accept").length,1);assert(h.find("Inspect reviewed model proposal"));await h.find("Inspect reviewed model proposal").fire("click");assert.match(h.body.textContent,/Proposal X-/);assert.equal(h.writes().length,2);});
